; ----------------------------------------------------------------------
; ############################################################
; PANTALLA DE PORTADA
; ############################################################
; Una imagen de SCREEN 2 ocupa 6144 bytes de patrones y otros
; 6144 de color (768 tiles x 8 lineas). Aqui se vuelcan los dos
; bloques enteros de una tacada y se enciende la pantalla.
; La tabla de nombres no se toca: INIGRP ya la dejo con la
; secuencia 0,1,2,...255 repetida, que es justo lo que hace
; falta para mostrar un bitmap a pantalla completa.
; ----------------------------------------------------------------------
PORTADA:		; Vuelca la imagen de portada a la VRAM y la muestra
	call 00041h		;88b8   ; BIOS DISSCR - Inhibits the screen display | Apaga la pantalla: volcar 12 KB a la VRAM se veria como un destrozo
	di			;88bb
	ld hl,0891ch		;88bc   ; Patrones de la imagen -> VRAM 0x0000 (los tres tercios de golpe)
	ld de,00000h		;88bf
	ld bc,01800h		;88c2
	call 0005ch		;88c5   ; BIOS LDIRVM - Block transfers to VRAM from memory
	di			;88c8
	ld hl,0a11ch		;88c9   ; Color de la imagen -> VRAM 0x2000 (los tres tercios)
	ld de,02000h		;88cc
	ld bc,01800h		;88cf
	call 0005ch		;88d2   ; BIOS LDIRVM - Block transfers to VRAM from memory
	call 00044h		;88d5   ; BIOS ENASCR - Displays the screen | Ya esta la imagen entera: encender pantalla
	ei			;88d8
	ret			;88d9   ; Vuelve al cargador, que seguira con el bloque del juego

